reference_prolog:
/* ---------- Statutory rules (excerpts) ---------- */

/* Additional standard deduction for aged or blind individuals */
additional_standard_deduction(Age, Amount) :-
    ( Age >= 65 ->
        Amount = 750
    ; Age < 65 ->
        Amount = 0
    ).

/* ---------- Facts for the case ---------- */

/* Alice's birth date and payment */
alice_birth_date(1950, 3, 2).
alice_payment(33200).

/* ---------- Derivation of Alice's additional standard deduction ---------- */

alice_additional_standard_deduction(Amount) :-
    alice_birth_date(Year, _, _),
    YearOfBirth is 2017 - Year,
    additional_standard_deduction(YearOfBirth, Amount).

/* ---------- Verification of the claim ---------- */

:- (  alice_additional_standard_deduction(Amount),
      Amount =:= 750
   -> format('Result: Entailment~n')
   ;  format('Result: Contradiction~n')
   ).
:- halt.
